'use client'

import React, { useEffect, useRef, useState } from 'react'
import DOMPurify from 'dompurify'

interface RawEditorProps {
    content?: string
    onChange?: (html: string) => void
    placeholder?: string
    className?: string
}

export default function RawEditor({
                                      content = '',
                                      onChange,
                                      placeholder = 'İçeriğinizi buraya yazın...',
                                      className = ''
                                  }: RawEditorProps) {
    const editorRef = useRef<HTMLDivElement | null>(null)
    const isUpdatingRef = useRef(false)
    const [isPurifyReady, setIsPurifyReady] = useState(false)
    const [html, setHtml] = useState<string>('')

    // Toolbar state
    const [foreColor, setForeColor] = useState('#000000')
    const [backColor, setBackColor] = useState('#ffffff')
    const [fontSize, setFontSize] = useState('16')
    const [showColorPicker, setShowColorPicker] = useState(false)
    const [showBgColorPicker, setShowBgColorPicker] = useState(false)

    useEffect(() => {
        if (typeof window !== 'undefined') setIsPurifyReady(true)
    }, [])

    const sanitizeConfig = {
        ALLOWED_TAGS: [
            'p', 'br', 'strong', 'b', 'em', 'i', 'u', 's', 'strike',
            'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
            'ul', 'ol', 'li',
            'a', 'img',
            'blockquote', 'code', 'pre',
            'span', 'div',
            'table', 'thead', 'tbody', 'tr', 'th', 'td',
            'mark', 'small', 'sub', 'sup', 'hr'
        ],
        ALLOWED_ATTR: [
            'style', 'class', 'id',
            'href', 'target', 'rel',
            'src', 'alt', 'width', 'height',
            'align', 'valign',
            'colspan', 'rowspan',
            'data-*'
        ],
        KEEP_CONTENT: true,
        ALLOWED_URI_REGEXP: /^(?:(?:(?:f|ht)tps?|mailto|tel|callto|cid|xmpp|data):|[^a-z]|[a-z+.\-]+(?:[^a-z+.\-:]|$))/i,
    } as DOMPurify.Config

    const sanitizeToString = (dirty: string) => {
        const res = DOMPurify.sanitize(dirty, sanitizeConfig)
        return typeof res === 'string' ? res : String(res)
    }

    const emitChange = (newHtml: string) => {
        setHtml(newHtml)
        if (onChange) onChange(newHtml)
    }

    useEffect(() => {
        if (!isPurifyReady) return
        if (content && editorRef.current && !isUpdatingRef.current) {
            const sanitized = sanitizeToString(content)
            if ((editorRef.current.innerHTML ?? '') !== sanitized) {
                editorRef.current.innerHTML = sanitized
                setHtml(sanitized)
            }
        }
    }, [content, isPurifyReady])

    const handleInput = (e: React.FormEvent<HTMLDivElement>) => {
        if (!isPurifyReady) return
        isUpdatingRef.current = true
        const rawHtml = e.currentTarget.innerHTML
        const clean = sanitizeToString(rawHtml)
        emitChange(clean)
        setTimeout(() => { isUpdatingRef.current = false }, 0)
    }

    const handlePaste = (e: React.ClipboardEvent<HTMLDivElement>) => {
        e.preventDefault()
        if (!isPurifyReady || !editorRef.current) return

        let pasted = e.clipboardData.getData('text/html')
        if (!pasted) {
            pasted = e.clipboardData.getData('text/plain')
            pasted = pasted
                .split('\n')
                .map(line => line.trim() ? `<p>${escapeHtml(line)}</p>` : '<br>')
                .join('')
        }

        const clean = sanitizeToString(pasted)

        const sel = window.getSelection()
        if (!sel?.rangeCount) return
        const range = sel.getRangeAt(0)
        range.deleteContents()
        const frag = range.createContextualFragment(clean)
        range.insertNode(frag)

        range.collapse(false)
        sel.removeAllRanges()
        sel.addRange(range)

        handleInput({ currentTarget: editorRef.current } as any)
    }

    const exec = (cmd: string, value?: string) => {
        try {
            document.execCommand(cmd, false, value)
            editorRef.current?.focus()
            if (editorRef.current) {
                setTimeout(() => {
                    if (editorRef.current) {
                        const clean = sanitizeToString(editorRef.current.innerHTML)
                        editorRef.current.innerHTML = clean
                        emitChange(clean)
                    }
                }, 0)
            }
        } catch (err) {
            console.warn('execCommand failed', err)
        }
    }

    const applyColor = (color: string, what: 'fore' | 'back') => {
        if (what === 'fore') {
            exec('foreColor', color)
            setForeColor(color)
            setShowColorPicker(false)
        } else {
            exec('hiliteColor', color)
            setBackColor(color)
            setShowBgColorPicker(false)
        }
    }

    const insertLink = () => {
        const url = prompt("Bağlantı URL'si (https://...)")
        if (!url) return
        exec('createLink', url)
    }

    const insertImage = () => {
        const url = prompt("Resim URL'si:")
        if (!url) return
        exec('insertImage', url)
    }

    const setHeading = (tag: string) => {
        exec('formatBlock', tag)
    }

    const setFontSizeCustom = (sizePx: string) => {
        const sel = window.getSelection()
        if (!sel || !sel.rangeCount) return
        const range = sel.getRangeAt(0)
        if (range.collapsed) return
        const span = document.createElement('span')
        span.style.fontSize = `${sizePx}px`
        try {
            span.appendChild(range.extractContents())
            range.insertNode(span)
            if (editorRef.current) {
                const clean = sanitizeToString(editorRef.current.innerHTML)
                editorRef.current.innerHTML = clean
                emitChange(clean)
            }
        } catch (err) {
            console.warn(err)
        }
        setFontSize(sizePx)
    }

    const alignText = (dir: 'left' | 'center' | 'right' | 'justify') => {
        const cmdMap = {
            left: 'justifyLeft',
            center: 'justifyCenter',
            right: 'justifyRight',
            justify: 'justifyFull'
        }
        exec(cmdMap[dir])
    }

    function escapeHtml(unsafe: string) {
        return unsafe.replace(/[&<>"']/g, function(m) {
            switch (m) {
                case '&': return '&amp;'
                case '<': return '&lt;'
                case '>': return '&gt;'
                case '"': return '&quot;'
                case "'": return '&#039;'
                default: return m
            }
        })
    }

    const colorPresets = [
        '#000000', '#FFFFFF', '#FF0000', '#00FF00', '#0000FF', '#FFFF00',
        '#FF00FF', '#00FFFF', '#FFA500', '#800080', '#FFC0CB', '#808080',
        '#8B4513', '#006400', '#000080', '#FF6347', '#4B0082', '#FFD700'
    ]

    if (!isPurifyReady) {
        return (
            <div className={`border rounded-lg p-4 min-h-[200px] bg-gray-50 ${className}`}>
                <p className="text-gray-400">Editör yükleniyor...</p>
            </div>
        )
    }

    return (
        <div className={`w-full space-y-3 ${className}`}>
            {/* Toolbar - Responsive */}
            <div className="bg-white border rounded-lg p-2 shadow-sm">
                {/* Row 1: Text Formatting */}
                <div className="flex flex-wrap gap-2 items-center pb-2 border-b">
                    {/* Bold, Italic, Underline, Strike */}
                    <div className="flex gap-1">
                        <button
                            type="button"
                            onClick={() => exec('bold')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 font-bold transition"
                            title="Kalın (Ctrl+B)"
                        >
                            B
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('italic')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 italic transition"
                            title="İtalik (Ctrl+I)"
                        >
                            I
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('underline')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 underline transition"
                            title="Altı Çizili (Ctrl+U)"
                        >
                            U
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('strikeThrough')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 line-through transition"
                            title="Üstü Çizili"
                        >
                            S
                        </button>
                    </div>

                    {/* Heading Select */}
                    <select
                        onChange={(e) => setHeading(e.target.value)}
                        defaultValue="p"
                        className="px-2 py-1 text-sm border rounded hover:bg-gray-50 transition focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                        <option value="p">Paragraf</option>
                        <option value="h1">Başlık 1</option>
                        <option value="h2">Başlık 2</option>
                        <option value="h3">Başlık 3</option>
                        <option value="h4">Başlık 4</option>
                        <option value="h5">Başlık 5</option>
                        <option value="h6">Başlık 6</option>
                    </select>

                    {/* Font Size */}
                    <select
                        value={fontSize}
                        onChange={(e) => setFontSizeCustom(e.target.value)}
                        className="px-2 py-1 text-sm border rounded hover:bg-gray-50 transition focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                        <option value="12">12px</option>
                        <option value="14">14px</option>
                        <option value="16">16px</option>
                        <option value="18">18px</option>
                        <option value="20">20px</option>
                        <option value="24">24px</option>
                        <option value="28">28px</option>
                        <option value="32">32px</option>
                        <option value="36">36px</option>
                    </select>

                    {/* Colors */}
                    <div className="flex gap-1">
                        {/* Text Color */}
                        <div className="relative">
                            <button
                                type="button"
                                onClick={() => {
                                    setShowColorPicker(!showColorPicker)
                                    setShowBgColorPicker(false)
                                }}
                                className="w-8 h-8 flex flex-col items-center justify-center rounded hover:bg-gray-100 transition"
                                title="Metin Rengi"
                            >
                                <span className="text-sm font-bold">A</span>
                                <div className="w-6 h-1 rounded mt-0.5" style={{ backgroundColor: foreColor }} />
                            </button>
                            {showColorPicker && (
                                <div className="absolute top-full left-0 mt-1 bg-white border rounded-lg shadow-lg p-3 z-50 min-w-[180px]">
                                    <div className="grid grid-cols-6 gap-1 mb-2">
                                        {colorPresets.map(color => (
                                            <button
                                                key={color}
                                                type="button"
                                                onClick={() => applyColor(color, 'fore')}
                                                className="w-6 h-6 rounded border-2 hover:scale-110 transition"
                                                style={{ backgroundColor: color }}
                                                title={color}
                                            />
                                        ))}
                                    </div>
                                    <input
                                        type="color"
                                        value={foreColor}
                                        onChange={(e) => applyColor(e.target.value, 'fore')}
                                        className="w-full h-8 cursor-pointer rounded"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Background Color */}
                        <div className="relative">
                            <button
                                type="button"
                                onClick={() => {
                                    setShowBgColorPicker(!showBgColorPicker)
                                    setShowColorPicker(false)
                                }}
                                className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                                title="Arka Plan Rengi"
                            >
                                <span className="px-1.5 py-0.5 text-sm font-bold rounded" style={{ backgroundColor: backColor }}>
                                    A
                                </span>
                            </button>
                            {showBgColorPicker && (
                                <div className="absolute top-full left-0 mt-1 bg-white border rounded-lg shadow-lg p-3 z-50 min-w-[180px]">
                                    <div className="grid grid-cols-6 gap-1 mb-2">
                                        {colorPresets.map(color => (
                                            <button
                                                key={color}
                                                type="button"
                                                onClick={() => applyColor(color, 'back')}
                                                className="w-6 h-6 rounded border-2 hover:scale-110 transition"
                                                style={{ backgroundColor: color }}
                                                title={color}
                                            />
                                        ))}
                                    </div>
                                    <input
                                        type="color"
                                        value={backColor}
                                        onChange={(e) => applyColor(e.target.value, 'back')}
                                        className="w-full h-8 cursor-pointer rounded"
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Row 2: Lists, Alignment, Insert */}
                <div className="flex flex-wrap gap-2 items-center pt-2">
                    {/* Lists */}
                    <div className="flex gap-1">
                        <button
                            type="button"
                            onClick={() => exec('insertUnorderedList')}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition flex items-center gap-1"
                            title="Madde İşaretli Liste"
                        >
                            <span>•</span> Liste
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('insertOrderedList')}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition flex items-center gap-1"
                            title="Numaralı Liste"
                        >
                            <span>1.</span> Liste
                        </button>
                    </div>

                    {/* Alignment */}
                    <div className="flex gap-1 border-l pl-2">
                        <button
                            type="button"
                            onClick={() => alignText('left')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="Sola Hizala"
                        >
                            ☰
                        </button>
                        <button
                            type="button"
                            onClick={() => alignText('center')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="Ortala"
                        >
                            ☰
                        </button>
                        <button
                            type="button"
                            onClick={() => alignText('right')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="Sağa Hizala"
                        >
                            ☰
                        </button>
                        <button
                            type="button"
                            onClick={() => alignText('justify')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="İki Yana Yasla"
                        >
                            ☰
                        </button>
                    </div>

                    {/* Indent */}
                    <div className="flex gap-1 border-l pl-2">
                        <button
                            type="button"
                            onClick={() => exec('indent')}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition"
                            title="Girintili"
                        >
                            →
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('outdent')}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition"
                            title="Çıkıntılı"
                        >
                            ←
                        </button>
                    </div>

                    {/* Insert */}
                    <div className="flex gap-1 border-l pl-2">
                        <button
                            type="button"
                            onClick={insertLink}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition"
                            title="Link Ekle"
                        >
                            🔗 Link
                        </button>
                        <button
                            type="button"
                            onClick={insertImage}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition"
                            title="Resim Ekle"
                        >
                            🖼️ Resim
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('insertHorizontalRule')}
                            className="px-2 py-1 text-sm rounded hover:bg-gray-100 transition"
                            title="Yatay Çizgi"
                        >
                            ―
                        </button>
                    </div>

                    {/* Undo/Redo & Clear */}
                    <div className="flex gap-1 border-l pl-2 ml-auto">
                        <button
                            type="button"
                            onClick={() => exec('undo')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="Geri Al (Ctrl+Z)"
                        >
                            ↶
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('redo')}
                            className="w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100 transition"
                            title="Yinele (Ctrl+Y)"
                        >
                            ↷
                        </button>
                        <button
                            type="button"
                            onClick={() => exec('removeFormat')}
                            className="px-2 py-1 text-sm rounded hover:bg-red-50 text-red-600 transition"
                            title="Formatı Temizle"
                        >
                            ✕
                        </button>
                    </div>
                </div>
            </div>

            {/* Editor Area */}
            <div
                ref={editorRef}
                contentEditable
                suppressContentEditableWarning
                onInput={handleInput}
                onPaste={handlePaste}
                className="w-full border-2 rounded-lg p-4 min-h-[300px] max-h-[600px] overflow-y-auto overflow-x-hidden focus:outline-none focus:border-blue-500 prose max-w-none bg-white transition"
                data-placeholder={placeholder}
            />

            {/* Global Styles */}
            <style jsx global>{`
                /* Placeholder */
                [contenteditable][data-placeholder]:empty:before {
                    content: attr(data-placeholder);
                    color: #9ca3af;
                    pointer-events: none;
                    position: absolute;
                }

                /* Editor Base */
                [contenteditable] {
                    word-wrap: break-word;
                    overflow-wrap: break-word;
                    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
                }

                [contenteditable] * {
                    max-width: 100%;
                }

                /* Images */
                [contenteditable] img {
                    max-width: 100%;
                    height: auto;
                    display: block;
                    margin: 0.5rem 0;
                    border-radius: 4px;
                }

                /* Tables */
                [contenteditable] table {
                    width: 100%;
                    border-collapse: collapse;
                    margin: 1rem 0;
                    overflow-x: auto;
                    display: block;
                }

                [contenteditable] table td,
                [contenteditable] table th {
                    border: 1px solid #e5e7eb;
                    padding: 0.5rem;
                    min-width: 50px;
                }

                [contenteditable] table th {
                    background-color: #f9fafb;
                    font-weight: 600;
                }

                /* Headings */
                [contenteditable] h1 {
                    font-size: clamp(1.75rem, 5vw, 2.5rem);
                    font-weight: 700;
                    margin: 1.5rem 0 0.75rem;
                    line-height: 1.2;
                }

                [contenteditable] h2 {
                    font-size: clamp(1.5rem, 4vw, 2rem);
                    font-weight: 700;
                    margin: 1.25rem 0 0.75rem;
                    line-height: 1.3;
                }

                [contenteditable] h3 {
                    font-size: clamp(1.25rem, 3vw, 1.75rem);
                    font-weight: 600;
                    margin: 1rem 0 0.5rem;
                    line-height: 1.4;
                }

                [contenteditable] h4 {
                    font-size: clamp(1.125rem, 2.5vw, 1.5rem);
                    font-weight: 600;
                    margin: 1rem 0 0.5rem;
                }

                [contenteditable] h5 {
                    font-size: clamp(1rem, 2vw, 1.25rem);
                    font-weight: 600;
                    margin: 0.875rem 0 0.5rem;
                }

                [contenteditable] h6 {
                    font-size: clamp(0.875rem, 1.5vw, 1.125rem);
                    font-weight: 600;
                    margin: 0.875rem 0 0.5rem;
                }

                /* Paragraphs */
                [contenteditable] p {
                    margin: 0.75rem 0;
                    line-height: 1.7;
                }

                /* Lists */
                [contenteditable] ul,
                [contenteditable] ol {
                    margin: 0.75rem 0;
                    padding-left: 2rem;
                }

                [contenteditable] li {
                    margin: 0.25rem 0;
                    line-height: 1.6;
                }

                /* Blockquote */
                [contenteditable] blockquote {
                    border-left: 4px solid #3b82f6;
                    padding-left: 1rem;
                    margin: 1rem 0;
                    color: #6b7280;
                    font-style: italic;
                }

                /* Code */
                [contenteditable] code {
                    background-color: #f3f4f6;
                    padding: 0.125rem 0.375rem;
                    border-radius: 0.25rem;
                    font-family: 'Courier New', monospace;
                    font-size: 0.875em;
                }

                [contenteditable] pre {
                    background-color: #1f2937;
                    color: #f9fafb;
                    padding: 1rem;
                    border-radius: 0.5rem;
                    overflow-x: auto;
                    margin: 1rem 0;
                }

                [contenteditable] pre code {
                    background-color: transparent;
                    padding: 0;
                    color: inherit;
                }

                /* Links */
                [contenteditable] a {
                    color: #3b82f6;
                    text-decoration: underline;
                    transition: color 0.2s;
                }

                [contenteditable] a:hover {
                    color: #2563eb;
                }

                /* HR */
                [contenteditable] hr {
                    border: none;
                    border-top: 2px solid #e5e7eb;
                    margin: 1.5rem 0;
                }

                /* Mobile Responsive */
                @media (max-width: 640px) {
                    [contenteditable] {
                        font-size: 14px;
                        padding: 0.75rem !important;
                    }

                    [contenteditable] table {
                        font-size: 12px;
                    }

                    [contenteditable] ul,
                    [contenteditable] ol {
                        padding-left: 1.25rem;
                    }
                }

                /* Tablet */
                @media (min-width: 641px) and (max-width: 1024px) {
                    [contenteditable] {
                        font-size: 15px;
                    }
                }

                /* Desktop */
                @media (min-width: 1025px) {
                    [contenteditable] {
                        font-size: 16px;
                    }
                }
            `}</style>
        </div>
    )
}